1	"use server";
2	
3	import { promises as fs } from "node:fs";
4	import { join } from "node:path";
5	import { spawn } from "node:child_process";
6	import { revalidatePath } from "next/cache";
7	import { db } from "./db";
8	import { requireAdmin } from "./auth";
9	
10	import { BOARD_UPLOAD_DIR, type StageAction } from "./board-shared";
11	
12	const DEFAULT_COLUMNS = ["Ideas", "Backlog", "In progress", "Review", "Done"];
13	
14	// Root of the deployed repo (where scripts/ lives). The web process runs from
15	// /opt/nxeon in production; process.cwd() is the safe, correct base for the
16	// relative script paths the pipeline actions invoke.
17	const PROJECT_ROOT = process.env.NXEON_PROJECT_ROOT ?? process.cwd();
18	const STAGE_LOG_DIR = join(BOARD_UPLOAD_DIR, "stage-logs");
19	
20	export type AppSummary = {
21	  id: string;
22	  name: string;
23	  slug: string;
24	  color: string | null;
25	  boardCount: number;
26	  // The real infrastructure Server this app is bound to, if any. Null = the app
27	  // is just a label (e.g. the Nxeon platform itself has no customer Server row).
28	  serverId: string | null;
29	  serverName: string | null;
30	  serverStatus: string | null;
31	};
32	export type ServerOption = { id: string; name: string; ipAddress: string | null; status: string };
33	export type BoardSummary = { id: string; name: string; cardCount: number; appId: string | null };
34	export type CardSummary = {
35	  id: string;
36	  title: string;
37	  type: string;
38	  priority: string;
39	  labels: string[];
40	  assignee: string | null;
41	  attachmentCount: number;
42	  commentCount: number;
43	  hasDescription: boolean;
44	  updatedAt: string;
45	};
46	export type CardSearchHit = {
47	  id: string;
48	  boardId: string;
49	  boardName: string;
50	  columnId: string;
51	  columnName: string;
52	  title: string;
53	  type: string;
54	  priority: string;
55	  snippet: string;
56	  matchedIn: "title" | "description" | "comment";
57	};
58	export type ColumnData = { id: string; name: string; position: number; cards: CardSummary[] };
59	export type BoardData = { id: string; name: string; columns: ColumnData[] };
60	export type CardDetail = CardSummary & {
61	  description: string;
62	  columnId: string;
63	  columnName: string;
64	  attachments: { id: string; filename: string; kind: string; mime: string; sizeBytes: number; url: string }[];
65	  comments: { id: string; authorName: string; body: string; createdAt: string }[];
66	};
67	
68	// ---- Apps ------------------------------------------------------------------
69	
70	function slugify(name: string): string {
71	  return name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "app";
72	}
73	
74	/** All apps/products, oldest first, with their board counts and bound server. */
75	export async function listApps(): Promise<AppSummary[]> {
76	  await requireAdmin();
77	  const apps = await db.app.findMany({
78	    orderBy: { createdAt: "asc" },
79	    include: { _count: { select: { boards: true } }, server: { select: { id: true, name: true, status: true } } },
80	  });
81	  return apps.map((a) => ({
82	    id: a.id,
83	    name: a.name,
84	    slug: a.slug,
85	    color: a.color,
86	    boardCount: a._count.boards,
87	    serverId: a.server?.id ?? null,
88	    serverName: a.server?.name ?? null,
89	    serverStatus: a.server?.status ?? null,
90	  }));
91	}
