93	/** Admin-gated list of real servers an app can be bound to (for the board's
94	 *  server picker). Newest first, capped — enough to choose from without loading
95	 *  the whole fleet. */
96	export async function listServersForBinding(): Promise<ServerOption[]> {
97	  await requireAdmin();
98	  const servers = await db.server.findMany({
99	    orderBy: { createdAt: "desc" },
100	    select: { id: true, name: true, ipAddress: true, status: true },
101	    take: 500,
102	  });
103	  return servers.map((s) => ({ id: s.id, name: s.name, ipAddress: s.ipAddress, status: s.status }));
104	}
