106	/** Bind an app to a real Server (or unbind with serverId=null). Admin-gated. */
107	export async function setAppServer(appId: string, serverId: string | null): Promise<{ error?: string }> {
108	  await requireAdmin();
109	  if (serverId) {
110	    const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true } });
111	    if (!server) return { error: "Server not found." };
112	  }
113	  await db.app.update({ where: { id: appId }, data: { serverId: serverId || null } }).catch(() => undefined);
114	  revalidatePath("/admin/board");
115	  return {};
116	}
117	
118	export async function createApp(name: string, color?: string | null): Promise<{ id?: string; error?: string }> {
119	  await requireAdmin();
120	  const clean = String(name ?? "").trim().slice(0, 60);
121	  if (!clean) return { error: "Enter an app name." };
122	  // Ensure a unique slug even when two apps share a base name.
123	  let slug = slugify(clean);
124	  for (let n = 2; await db.app.findUnique({ where: { slug } }); n++) slug = `${slugify(clean)}-${n}`;
125	  const app = await db.app.create({ data: { name: clean, slug, color: color?.trim() || null } });
126	  revalidatePath("/admin/board");
127	  return { id: app.id };
128	}
