130	/** All boards, oldest first. Optionally filtered to one app. Seeds a default
131	 *  "Nxeon" board (attached to the Nxeon app when present) on first use. */
132	export async function listBoards(appId?: string | null): Promise<BoardSummary[]> {
133	  await requireAdmin();
134	  const where = appId ? { appId } : {};
135	  let boards = await db.board.findMany({ where, orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
136	  // Only seed when the whole board table is empty (never when a filter just
137	  // happens to match nothing).
138	  if (!appId && (await db.board.count()) === 0) {
139	    const nxeonApp = await db.app.findUnique({ where: { slug: "nxeon" } });
140	    await createBoardInternal("Nxeon", nxeonApp?.id ?? null);
141	    boards = await db.board.findMany({ where, orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
142	  }
143	  return boards.map((b) => ({ id: b.id, name: b.name, cardCount: b._count.cards, appId: b.appId }));
144	}
145	
146	async function createBoardInternal(name: string, appId?: string | null): Promise<string> {
147	  const board = await db.board.create({ data: { name, appId: appId ?? null } });
148	  await db.boardColumn.createMany({ data: DEFAULT_COLUMNS.map((n, i) => ({ boardId: board.id, name: n, position: i })) });
149	  return board.id;
150	}
