152	export async function createBoard(name: string, appId?: string | null): Promise<{ id?: string; error?: string }> {
153	  await requireAdmin();
154	  const clean = String(name ?? "").trim().slice(0, 60);
155	  if (!clean) return { error: "Enter a board name." };
156	  const id = await createBoardInternal(clean, appId ?? null);
157	  revalidatePath("/admin/board");
158	  return { id };
159	}
