161	export async function renameBoard(id: string, name: string): Promise<void> {
162	  await requireAdmin();
163	  const clean = String(name ?? "").trim().slice(0, 60);
164	  if (clean) await db.board.update({ where: { id }, data: { name: clean } });
165	  revalidatePath("/admin/board");
166	}
