168	export async function deleteBoard(id: string): Promise<void> {
169	  await requireAdmin();
170	  await db.board.delete({ where: { id } }).catch(() => undefined);
171	  await fs.rm(join(BOARD_UPLOAD_DIR, "board", id), { recursive: true, force: true }).catch(() => undefined);
172	  revalidatePath("/admin/board");
173	}
