175	/** Full board with columns + card summaries (non-archived). */
176	export async function getBoard(boardId: string): Promise<BoardData | null> {
177	  await requireAdmin();
178	  const board = await db.board.findUnique({
179	    where: { id: boardId },
180	    include: {
181	      columns: {
182	        orderBy: { position: "asc" },
183	        include: {
184	          cards: {
185	            where: { archivedAt: null },
186	            orderBy: { position: "asc" },
187	            include: { _count: { select: { attachments: true, comments: true } } },
188	          },
189	        },
190	      },
191	    },
192	  });
193	  if (!board) return null;
194	  return {
195	    id: board.id,
196	    name: board.name,
197	    columns: board.columns.map((c) => ({
198	      id: c.id,
199	      name: c.name,
200	      position: c.position,
201	      cards: c.cards.map((card) => ({
202	        id: card.id,
203	        title: card.title,
204	        type: card.type,
205	        priority: card.priority,
206	        labels: card.labels,
207	        assignee: card.assignee,
208	        attachmentCount: card._count.attachments,
209	        commentCount: card._count.comments,
210	        hasDescription: card.description.trim().length > 0,
211	        updatedAt: card.updatedAt.toISOString(),
212	      })),
213	    })),
214	  };
215	}
