217	// ---- Columns ---------------------------------------------------------------
218	
219	export async function createColumn(boardId: string, name: string): Promise<void> {
220	  await requireAdmin();
221	  const clean = String(name ?? "").trim().slice(0, 40);
222	  if (!clean) return;
223	  const max = await db.boardColumn.aggregate({ where: { boardId }, _max: { position: true } });
224	  await db.boardColumn.create({ data: { boardId, name: clean, position: (max._max.position ?? -1) + 1 } });
225	  revalidatePath("/admin/board");
226	}
227	
228	export async function renameColumn(id: string, name: string): Promise<void> {
229	  await requireAdmin();
230	  const clean = String(name ?? "").trim().slice(0, 40);
231	  if (clean) await db.boardColumn.update({ where: { id }, data: { name: clean } });
232	  revalidatePath("/admin/board");
233	}
234	
235	export async function deleteColumn(id: string): Promise<{ error?: string }> {
236	  await requireAdmin();
237	  const cards = await db.card.count({ where: { columnId: id, archivedAt: null } });
238	  if (cards > 0) return { error: "Move or archive its cards first." };
239	  await db.boardColumn.delete({ where: { id } }).catch(() => undefined);
240	  revalidatePath("/admin/board");
241	  return {};
242	}
243	
244	/** Reorder a column within its board; renumber siblings. */
245	export async function moveColumn(columnId: string, toIndex: number): Promise<void> {
246	  await requireAdmin();
247	  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
248	  if (!col) return;
249	  const siblings = await db.boardColumn.findMany({
250	    where: { boardId: col.boardId, NOT: { id: columnId } },
251	    orderBy: { position: "asc" },
252	    select: { id: true },
253	  });
254	  const order = siblings.map((s) => s.id);
255	  const idx = Math.max(0, Math.min(toIndex, order.length));
256	  order.splice(idx, 0, columnId);
257	  await db.$transaction(order.map((id, i) => db.boardColumn.update({ where: { id }, data: { position: i } })));
258	  revalidatePath("/admin/board");
259	}
