261	// ---- Search ----------------------------------------------------------------
262	
263	/** Full-text-ish search over card title, description and comment bodies
264	 *  (Postgres case-insensitive contains). Scoped to a board, or to an app (all
265	 *  its boards). Skips archived cards. */
266	export async function searchCards(
267	  scope: { boardId?: string | null; appId?: string | null },
268	  query: string,
269	): Promise<CardSearchHit[]> {
270	  await requireAdmin();
271	  const q = String(query ?? "").trim();
272	  if (q.length < 2) return [];
273	  const boardWhere =
274	    scope.boardId ? { boardId: scope.boardId } : scope.appId ? { board: { appId: scope.appId } } : {};
275	  const cards = await db.card.findMany({
276	    where: {
277	      archivedAt: null,
278	      ...boardWhere,
279	      OR: [
280	        { title: { contains: q, mode: "insensitive" } },
281	        { description: { contains: q, mode: "insensitive" } },
282	        { comments: { some: { body: { contains: q, mode: "insensitive" } } } },
283	      ],
284	    },
285	    include: {
286	      board: { select: { name: true } },
287	      column: { select: { name: true } },
288	      comments: { where: { body: { contains: q, mode: "insensitive" } }, take: 1, orderBy: { createdAt: "desc" } },
289	    },
290	    orderBy: { updatedAt: "desc" },
291	    take: 50,
292	  });
293	  const lower = q.toLowerCase();
294	  const snippetAround = (text: string): string => {
295	    const i = text.toLowerCase().indexOf(lower);
296	    if (i < 0) return text.slice(0, 120);
297	    const start = Math.max(0, i - 40);
298	    return (start > 0 ? "…" : "") + text.slice(start, i + q.length + 60).trim() + (i + q.length + 60 < text.length ? "…" : "");
299	  };
300	  return cards.map((c) => {
301	    let matchedIn: CardSearchHit["matchedIn"] = "title";
302	    let snippet = c.title;
303	    if (!c.title.toLowerCase().includes(lower)) {
304	      if (c.description.toLowerCase().includes(lower)) {
305	        matchedIn = "description";
306	        snippet = snippetAround(c.description);
307	      } else if (c.comments[0]) {
308	        matchedIn = "comment";
309	        snippet = snippetAround(c.comments[0].body);
310	      }
311	    }
312	    return {
313	      id: c.id,
314	      boardId: c.boardId,
315	      boardName: c.board.name,
316	      columnId: c.columnId,
317	      columnName: c.column.name,
318	      title: c.title,
319	      type: c.type,
320	      priority: c.priority,
321	      snippet,
322	      matchedIn,
323	    };
324	  });
325	}
