327	// ---- Cards -----------------------------------------------------------------
328	
329	const TYPES = ["IDEA", "FEATURE", "BUG", "CHORE"];
330	const PRIORITIES = ["LOW", "NORMAL", "HIGH", "URGENT"];
331	
332	export async function createCard(columnId: string, title: string, type = "FEATURE"): Promise<{ id?: string; error?: string }> {
333	  await requireAdmin();
334	  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
335	  if (!col) return { error: "Column not found." };
336	  const clean = String(title ?? "").trim().slice(0, 200);
337	  if (!clean) return { error: "Enter a title." };
338	  const max = await db.card.aggregate({ where: { columnId }, _max: { position: true } });
339	  const card = await db.card.create({
340	    data: { boardId: col.boardId, columnId, title: clean, type: (TYPES.includes(type) ? type : "FEATURE") as never, position: (max._max.position ?? -1) + 1 },
341	  });
342	  revalidatePath("/admin/board");
343	  return { id: card.id };
344	}
345	
346	export async function updateCard(
347	  id: string,
348	  patch: { title?: string; description?: string; type?: string; priority?: string; labels?: string[]; assignee?: string | null },
349	): Promise<{ error?: string }> {
350	  await requireAdmin();
351	  const data: Record<string, unknown> = {};
352	  if (patch.title !== undefined) { const t = patch.title.trim().slice(0, 200); if (!t) return { error: "Title can’t be empty." }; data.title = t; }
353	  if (patch.description !== undefined) data.description = patch.description.slice(0, 20_000);
354	  if (patch.type !== undefined && TYPES.includes(patch.type)) data.type = patch.type;
355	  if (patch.priority !== undefined && PRIORITIES.includes(patch.priority)) data.priority = patch.priority;
356	  if (patch.labels !== undefined) data.labels = patch.labels.map((l) => l.trim().slice(0, 24)).filter(Boolean).slice(0, 8);
357	  if (patch.assignee !== undefined) data.assignee = patch.assignee?.trim().slice(0, 40) || null;
358	  await db.card.update({ where: { id }, data });
359	  revalidatePath("/admin/board");
360	  return {};
361	}
362	
363	/** Move a card to a column at a position; renumber siblings. */
364	export async function moveCard(cardId: string, toColumnId: string, toIndex: number): Promise<void> {
365	  await requireAdmin();
366	  const card = await db.card.findUnique({ where: { id: cardId }, select: { columnId: true, boardId: true } });
367	  const col = await db.boardColumn.findUnique({ where: { id: toColumnId }, select: { boardId: true } });
368	  if (!card || !col || col.boardId !== card.boardId) return;
369	  const siblings = await db.card.findMany({ where: { columnId: toColumnId, archivedAt: null, NOT: { id: cardId } }, orderBy: { position: "asc" }, select: { id: true } });
370	  const order = siblings.map((s) => s.id);
371	  const idx = Math.max(0, Math.min(toIndex, order.length));
372	  order.splice(idx, 0, cardId);
373	  await db.$transaction([
374	    db.card.update({ where: { id: cardId }, data: { columnId: toColumnId } }),
375	    ...order.map((id, i) => db.card.update({ where: { id }, data: { position: i } })),
376	  ]);
377	  revalidatePath("/admin/board");
378	}
