436	// ---- Execution pipeline ----------------------------------------------------
437	// Moving a card through stages can trigger real work: rendering docs, deploying
438	// to staging, promoting to production, or committing to GitHub. These are NEVER
439	// fired automatically by moveCard — they are only run when a human clicks the
440	// explicit, confirm-gated button in the card modal (see runCardStageAction).
441	// Each run is spawned DETACHED with output captured to a log file; a start
442	// comment is posted immediately and a completion comment (with the log tail) is
443	// posted when the child exits, so the request thread never blocks on a long
444	// deploy.
445	
446	// Fixed command table — actions are chosen from this allowlist only; no user
447	// input is ever interpolated into a shell command. The GitHub commit message is
448	// passed via an environment variable and expanded inside double quotes, so its
449	// contents can't break out into further shell parsing.
450	const STAGE_ACTIONS: Record<StageAction, { label: string; cmd: string; args: string[] }> = {
451	  docs: { label: "Publish to docs", cmd: "node", args: ["scripts/publish-docs.mjs"] },
452	  staging: { label: "Deploy to staging", cmd: "bash", args: ["scripts/deploy-staging.sh"] },
453	  production: { label: "Promote to production", cmd: "bash", args: ["scripts/promote-production.sh"] },
454	  github: { label: "Commit to GitHub", cmd: "bash", args: ["-c", 'git add -A && git commit -m "$NXEON_COMMIT_MSG"'] },
455	};
456	
457	async function readLogTail(logPath: string, max = 4000): Promise<string> {
458	  try {
459	    const buf = await fs.readFile(logPath, "utf8");
460	    return buf.length > max ? "…" + buf.slice(-max) : buf || "(no output)";
461	  } catch {
462	    return "(log unavailable)";
463	  }
464	}
465	
466	/**
467	 * Run a pipeline action for a card. Admin-gated. Spawns the mapped script
468	 * detached with output captured to a per-run log, records a start comment, and
469	 * (when the child exits) a completion comment with the log tail. Returns as soon
470	 * as the child is launched — it never waits for a long deploy to finish.
471	 */
472	export async function runCardStageAction(
473	  cardId: string,
474	  action: StageAction,
475	): Promise<{ error?: string; started?: boolean; logPath?: string }> {
476	  const admin = await requireAdmin();
477	  const spec = STAGE_ACTIONS[action];
478	  if (!spec) return { error: "Unknown action." };
479	  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true, title: true } });
480	  if (!card) return { error: "Card not found." };
481	
482	  await fs.mkdir(STAGE_LOG_DIR, { recursive: true });
483	  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
484	  const logPath = join(STAGE_LOG_DIR, `${cardId}-${action}-${stamp}.log`);
485	
486	  const env: NodeJS.ProcessEnv = { ...process.env };
487	  if (action === "github") {
488	    env.NXEON_COMMIT_MSG = `board: ${card.title} (card ${cardId})`.replace(/\s+/g, " ").slice(0, 180);
489	  }
490	
491	  const author = admin.email.split("@")[0];
492	  await db.cardComment.create({
493	    data: { cardId, authorName: author, body: `▶️ Started **${spec.label}**.\nLog: \`${logPath}\`` },
494	  });
495	
496	  let logFd;
497	  try {
498	    logFd = await fs.open(logPath, "a");
499	  } catch (e) {
500	    return { error: `Could not open log file: ${(e as Error).message}` };
501	  }
502	
503	  try {
504	    const child = spawn(spec.cmd, spec.args, {
505	      cwd: PROJECT_ROOT,
506	      env,
507	      detached: true,
