1	/**
2	 * One-off backfill for `Server.termPromoPercent` (added 2026-07-26).
3	 *
4	 * WHY. `prorateDeltaCents` used to default its rate basis to `currentPromo(now)`,
5	 * so a resize was priced off whatever seasonal promo happened to be running when
6	 * the customer clicked — letting them upgrade under a 45% basis and downgrade under
7	 * a 15% one and keep the spread on every remaining month. The fix records the rate
8	 * each term was ACTUALLY sold at on the server row. Rows that predate the column
9	 * are NULL, and NULL must never quietly fall back to today's promo, because that is
10	 * the bug itself. This script fills them from the billing record.
11	 *
12	 * HOW, in strict order of evidence. Each row reports which rule fired.
13	 *
14	 *   1. free / no expiry      -> 100 (gifted; nothing was sold, nothing prorates)
15	 *   2. game plan             -> 0   (orderGameServer charges gp.priceCents flat:
16	 *                                    no term discount, no promo, and renewalCharge
17	 *                                    renews at that same flat price)
18	 *   3. INVOICE for the current term -> the percent stated on the document
19	 *   4. WALLET TRANSACTION for the order -> same, for rows that predate invoicing
20	 *   5. otherwise             -> the conservative fallback (see below)
21	 *
22	 * Rules 3 and 4 read what the customer was genuinely billed. Both an order and a
23	 * renewal write their description from the same templates the code still uses:
24	 *   order:   "Order: <Plan> VPS (<hostname>) — <Term> · <Promo> NN% off first term"
25	 *   renewal: "Renewal: <Plan> VPS (<hostname>) — <Term>"          (no promo, ever)
26	 * so "NN% off first term" is the sold percent, and a renewal is 0% by definition —
27	 * lib/promotions.ts guarantees renewals never receive the intro discount. The
28	 * current term's document is identified by `periodEnd` landing on the server's
29	 * `expiresAt` (they are written from two separate `new Date()` calls milliseconds
30	 * apart, hence the tolerance) AND by carrying the hostname, so one user's several
31	 * servers cannot cross-match.
32	 *
33	 * Every derived percent is CROSS-CHECKED arithmetically against the cash actually
34	 * taken: recompute what that percent implies the charge should have been and
35	 * compare. A mismatch is reported loudly rather than written silently.
36	 *
37	 * THE FALLBACK IS NOT "FULL PRICE". The intuitive conservative guess — assume they
38	 * paid undiscounted list — is the money-printing direction: a credit is
39	 * monotonically increasing in the rate basis, so 0% off produces the LARGEST credit
40	 * this platform can emit, and for anyone who really bought under a deep promo it
41	 * pays out more cash than they ever handed over. The safe assumption is the
42	 * opposite: the LEAST we have ever charged (`deepestPromoPercent()`). See
43	 * lib/proration.ts `resolveTermPromoPercent` for the worked numbers.
44	 *
45	 * IDEMPOTENT: only ever touches rows where the column IS NULL. Re-running is a
46	 * no-op. Pass --apply to write; the default is a dry run.
47	 *
48	 *   npx tsx scripts/backfill-term-promo-percent.ts            # dry run
49	 *   npx tsx scripts/backfill-term-promo-percent.ts --apply    # write
50	 */
51	
52	import { db } from "../lib/db";
53	import { vpsTermPriceCents } from "../lib/billing-terms";
54	import { deepestPromoPercent, discountedCents } from "../lib/promotions";
55	
56	const APPLY = process.argv.includes("--apply");
57	
58	/** Tolerance when matching a billing document's periodEnd to `expiresAt`. */
59	const PERIOD_MATCH_MS = 60_000;
60	
61	/** "… · Summer Sale 30% off first term" -> 30. No note at all means full price. */
62	function promoPercentFromDescription(description: string): number | null {
63	  const m = /(\d{1,3})%\s*off\s*first\s*term/i.exec(description);
64	  if (!m) return null;
65	  const pct = Number(m[1]);
66	  return Number.isFinite(pct) && pct >= 0 && pct <= 100 ? pct : null;
67	}
68	
69	type Resolution = {
70	  percent: number;
71	  rule: string;
72	  evidence: string;
73	  /** Set when the arithmetic cross-check disagreed with the stated percent. */
74	  warning?: string;
75	};
76	
77	async function resolveServer(s: {
78	  id: string;
79	  hostname: string;
80	  userId: string;
81	  isFree: boolean;
82	  expiresAt: Date | null;
83	  termMonths: number;
84	  gamePlanId: string | null;
85	  plan: { name: string; priceCents: number };
86	  gamePlan: { name: string; priceCents: number } | null;
87	}): Promise<Resolution> {
88	  if (s.isFree || !s.expiresAt) {
89	    return {
90	      percent: 100,
91	      rule: "gifted",
92	      evidence: s.isFree ? "isFree" : "no expiresAt — nothing was sold",
93	    };
94	  }
95	
96	  if (s.gamePlanId) {
97	    // Flat all-in price, no term discount and no promo on either the order or the
98	    // renewal. Cross-check against the cash: the order debits exactly priceCents.
99	    const tx = await db.walletTransaction.findFirst({
100	      where: { userId: s.userId, description: { startsWith: "Game server:" } },
101	      orderBy: { createdAt: "desc" },
102	    });
103	    const expected = s.gamePlan?.priceCents ?? null;
104	    const paid = tx ? Math.abs(tx.amountCents) : null;
105	    return {
106	      percent: 0,
107	      rule: "game-plan-flat-price",
108	      evidence: `gamePlan "${s.gamePlan?.name}" @ ${expected}c, wallet debit ${paid ?? "n/a"}c`,
109	      warning:
110	        expected !== null && paid !== null && expected !== paid
111	          ? `game plan price ${expected}c but ${paid}c was debited`
112	          : undefined,
113	    };
114	  }
115	
116	  // The billing document that bought the term currently on the clock.
117	  const lo = new Date(s.expiresAt.getTime() - PERIOD_MATCH_MS);
118	  const hi = new Date(s.expiresAt.getTime() + PERIOD_MATCH_MS);
119	  const invoice = await db.invoice.findFirst({
120	    where: {
121	      userId: s.userId,
122	      periodEnd: { gte: lo, lte: hi },
123	      description: { contains: `(${s.hostname})` },
124	    },
125	    orderBy: { createdAt: "desc" },
126	  });
127	
128	  const doc = invoice
129	    ? { kind: "invoice", ref: `#${invoice.number}`, description: invoice.description, cents: invoice.amountCents }
130	    : await (async () => {
131	        // Rows that predate invoicing still have the wallet debit, written from the
132	        // same description template.
133	        const tx = await db.walletTransaction.findFirst({
134	          where: {
135	            userId: s.userId,
136	            amountCents: { lt: 0 },
137	            description: { contains: `(${s.hostname})` },
138	            OR: [{ description: { startsWith: "Order:" } }, { description: { startsWith: "Renewal:" } }],
139	          },
140	          orderBy: { createdAt: "desc" },
141	        });
142	        return tx
143	          ? { kind: "wallet-tx", ref: tx.createdAt.toISOString(), description: tx.description, cents: Math.abs(tx.amountCents) }
144	          : null;
145	      })();
146	
147	  if (!doc) {
148	    return {
149	      percent: deepestPromoPercent(),
150	      rule: "FALLBACK-deepest-discount",
151	      evidence: "no invoice and no wallet transaction names this hostname",
152	      warning: "rate genuinely unrecoverable — using the conservative floor",
153	    };
154	  }
155	
156	  const stated = promoPercentFromDescription(doc.description);
157	  const isRenewal = /^Renewal:/i.test(doc.description);
158	  const percent = stated ?? 0;
159	  const rule = stated !== null ? `${doc.kind}-promo-note` : isRenewal ? `${doc.kind}-renewal-full-price` : `${doc.kind}-no-promo-note`;
160	
161	  // Cross-check: what should that percent have cost for the PLAN alone? The
162	  // document total can legitimately exceed it (a dedicated IP and extra disk are
163	  // billed at full price on their own lines, and the wallet debit is one number for
164	  // the lot), so the plan charge is a lower bound on the total, never an equality.
165	  const regular = vpsTermPriceCents(s.plan.priceCents, s.termMonths);
166	  const implied = discountedCents(regular, percent);
167	  const warning =
168	    doc.cents < implied
169	      ? `document total ${doc.cents}c is BELOW the ${implied}c that ${percent}% off implies for the plan alone`
170	      : undefined;
171	
172	  return {
173	    percent,
174	    rule,
175	    evidence: `${doc.kind} ${doc.ref} "${doc.description}" total ${doc.cents}c (plan at ${percent}% off = ${implied}c of it)`,
176	    warning,
177	  };
178	}
179	
180	async function main() {
181	  const servers = await db.server.findMany({
182	    where: { termPromoPercent: null },
183	    include: { plan: true, gamePlan: true },
184	    orderBy: { createdAt: "asc" },
185	  });
186	
187	  const total = await db.server.count();
188	  console.log(`[backfill] ${total} server row(s) total; ${servers.length} with termPromoPercent = NULL`);
189	  console.log(`[backfill] mode: ${APPLY ? "APPLY (writing)" : "DRY RUN (pass --apply to write)"}`);
190	  console.log(`[backfill] conservative fallback for unrecoverable rows: ${deepestPromoPercent()}% off\n`);
191	
192	  const byRule = new Map<string, number>();
193	  let warnings = 0;
194	  let written = 0;
195	
196	  for (const s of servers) {
197	    const r = await resolveServer(s);
198	    byRule.set(r.rule, (byRule.get(r.rule) ?? 0) + 1);
199	    console.log(`  ${s.hostname} (${s.id})`);
200	    console.log(`      -> ${r.percent}% off   [${r.rule}]`);
201	    console.log(`         ${r.evidence}`);
202	    if (r.warning) {
203	      warnings++;
204	      console.log(`         !! ${r.warning}`);
205	    }
206	    if (APPLY) {
207	      // Guarded on NULL so a concurrent write (a renewal landing mid-run) wins
208	      // rather than being clobbered by a backfilled guess.
209	      const res = await db.server.updateMany({
210	        where: { id: s.id, termPromoPercent: null },
211	        data: { termPromoPercent: r.percent },
212	      });
213	      written += res.count;
214	      if (res.count === 0) console.log(`         (skipped: another writer set it first)`);
215	    }
216	  }
217	
218	  console.log(`\n[backfill] by rule:`);
219	  for (const [rule, n] of [...byRule.entries()].sort()) console.log(`    ${n}  ${rule}`);
220	  console.log(`[backfill] warnings: ${warnings}`);
221	  console.log(`[backfill] rows written: ${APPLY ? written : 0}`);
222	
223	  const stillNull = await db.server.count({ where: { termPromoPercent: null } });
224	  console.log(`[backfill] rows still NULL after this run: ${stillNull}`);
225	}
226	
227	main()
228	  .catch((e) => {
229	    console.error(e);
230	    process.exitCode = 1;
231	  })
232	  .finally(() => db.$disconnect());
