// Edit an app's working context: colour, bound server, code path, repo URL, and a
// free-form markdown context (stack / build / deploy / gotchas). A drawer so these
// live-but-rarely-touched fields don't clutter the board header. The context is
// the Claude-facing "how do I build/deploy this app" note.
function AppSettingsModal({
  app, servers, onClose, onSaved,
}: {
  app: AppSummary;
  servers: ServerOption[] | null;
  onClose: () => void;
  onSaved: () => void;
}) {
  const [color, setColor] = useState(app.color ?? "#7c5cf7");
  const [serverId, setServerId] = useState(app.serverId ?? "");
  const [codePath, setCodePath] = useState(app.codePath ?? "");
  const [repoUrl, setRepoUrl] = useState(app.repoUrl ?? "");
  const [context, setContext] = useState(app.context ?? "");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    function onKey(e: KeyboardEvent) { if (e.key === "Escape") onClose(); }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  async function save() {
    setSaving(true);
    try {
      const meta = await updateAppMeta(app.id, { codePath, repoUrl, context, color });
      if (meta.error) { alert(meta.error); return; }
      // Server binding lives on its own action; only call it when it changed.
      if ((serverId || null) !== (app.serverId ?? null)) {
        const bind = await setAppServer(app.id, serverId || null);
        if (bind.error) { alert(bind.error); return; }
      }
      onSaved();
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="fixed inset-0 z-40 flex items-start justify-center overflow-y-auto bg-black/60 p-4 sm:p-8" onMouseDown={onClose}>
      <div
        className="my-4 w-full max-w-2xl rounded-2xl border border-white/10 bg-navy-900 p-5 shadow-2xl"
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div className="mb-4 flex items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <span className="h-2.5 w-2.5 rounded-full" style={{ background: color }} />
            <h2 className="text-lg font-semibold text-white">{app.name} — settings</h2>
          </div>
          <button onClick={onClose} className="rounded-lg px-2 py-1 text-slate-400 hover:bg-white/5" aria-label="Close">✕</button>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <label className="text-sm">
            <span className="mb-1 block text-xs font-medium uppercase tracking-wider text-slate-400">Colour</span>
            <div className="flex items-center gap-2">
              <input type="color" value={color} onChange={(e) => setColor(e.target.value)} className="h-9 w-12 cursor-pointer rounded border border-white/10 bg-transparent p-0.5" />
              <input value={color} onChange={(e) => setColor(e.target.value)} className="input flex-1 py-1.5 text-sm" />
            </div>
          </label>

          <label className="text-sm">
            <span className="mb-1 block text-xs font-medium uppercase tracking-wider text-slate-400">Bound server</span>
            <select className="input w-full py-1.5 text-sm" value={serverId} onChange={(e) => setServerId(e.target.value)}>
              <option value="">{servers === null ? "loading…" : "— unbound —"}</option>
              {(servers ?? []).map((s) => (
                <option key={s.id} value={s.id}>{s.name}{s.ipAddress ? ` (${s.ipAddress})` : ""}</option>
              ))}
            </select>
          </label>

          <label className="text-sm sm:col-span-2">
            <span className="mb-1 block text-xs font-medium uppercase tracking-wider text-slate-400">Code path</span>
            <input value={codePath} onChange={(e) => setCodePath(e.target.value)} placeholder="/opt/nxeon" className="input w-full py-1.5 font-mono text-sm" />
          </label>

          <label className="text-sm sm:col-span-2">
            <span className="mb-1 block text-xs font-medium uppercase tracking-wider text-slate-400">Repo URL</span>
            <input value={repoUrl} onChange={(e) => setRepoUrl(e.target.value)} placeholder="https://github.com/org/repo (blank if none)" className="input w-full py-1.5 font-mono text-sm" />
          </label>

          <label className="text-sm sm:col-span-2">
            <span className="mb-1 block text-xs font-medium uppercase tracking-wider text-slate-400">
              Working context <span className="normal-case text-slate-500">— markdown: stack, build/deploy steps, conventions, gotchas</span>
            </span>
            <textarea
              value={context}
              onChange={(e) => setContext(e.target.value)}
              rows={12}
              placeholder="Stack, where the code lives, how to build & deploy, containers/services, gotchas…"
              className="input w-full py-2 font-mono text-xs leading-relaxed"
            />
          </label>
        </div>

        <div className="mt-5 flex items-center justify-end gap-2">
          <button onClick={onClose} className="rounded-lg px-3 py-1.5 text-sm text-slate-300 hover:bg-white/5">Cancel</button>
          <button
            onClick={save}
            disabled={saving}
            className="rounded-lg bg-brand-500 px-4 py-1.5 text-sm font-medium text-white hover:bg-brand-400 disabled:opacity-50"
          >
            {saving ? "Saving…" : "Save"}
          </button>
        </div>
      </div>
    </div>
  );
}
